import{_ as s,o as n,c as r,j as e,a as t}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"Rust","description":"","frontmatter":{"name":"Rust","quadrant":"languages-and-frameworks","history":[{"edition":"2026.3","ring":"adopt"}],"adr":"1631648331","tags":["rust","backend","cli","embedded","gui","wasm","sandbox"]},"headers":[],"relativePath":"radar/items/rust.md","filePath":"radar/items/rust.md"}'),i={name:"radar/items/rust.md"};function o(d,a,l,u,c,h){return n(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"rust",tabindex:"-1"},[t("Rust "),e("a",{class:"header-anchor",href:"#rust","aria-label":'Permalink to "Rust"'},"​")],-1),e("p",null,"Rust is the language for new services and programs, from systems and embedded software through command line tools, web servers, and background jobs, up to desktop GUIs. One toolchain and one set of conventions replace the per-language pipelines we used to keep in parallel.",-1),e("p",null,"It sits in Adopt because of where its trust comes from. Linus Torvalds accepted Rust into the Linux kernel, the first language besides C and assembly admitted there. A language trusted to write kernel drivers is one we can trust for everything above it, and that is what makes a single language across the whole stack viable.",-1),e("p",null,"WebAssembly carries almost as much weight, because it takes the same Rust code where a native binary cannot go. It runs as a sandboxed component on a server-side runtime when its dependencies and the host capabilities it needs are available under WASI, it renders in the browser alongside the server code it shares an implementation with, and it isolates untrusted code such as customer-provided extensions and plugins inside our own services, behind host interfaces we define. Wasmtime, the reference runtime for the component model and WASI, is written in Rust, so embedding the runtime and defining the host side of a sandbox happen in the same language as everything else. Browser code written in JavaScript or TypeScript is not part of this placement.",-1),e("p",null,"It also covers every shape of software we write without a language runtime to ship alongside it. Built for a static target such as musl, a CLI is a single file and a service image carries little beyond the program, and the compiler catches data races, missing null handling, and ignored errors before they reach production.",-1),e("p",null,"Starting new work in another language needs its own ADR with a precise technical write-up: the measurable requirement Rust fails, the evidence for it, the Rust options ruled out, and when the exception ends.",-1),e("p",null,[t("See "),e("a",{href:"./../../adrs/1631648331/README.html"},"ADR#1631648331"),t(".")],-1)])])}const g=s(i,[["render",o]]);export{p as __pageData,g as default};
